/******** Bit definition for MDMA_ID register  ********/
#define MDMA_ID_NBR_SHIFT (0)
#define MDMA_ID_NBR_MASK (0xFFFFFFFF << MDMA_ID_NBR_SHIFT) /* NBR */

/******** Bit definition for MDMA_VERSION register  ********/
#define MDMA_VERSION_NBR_SHIFT (0)
#define MDMA_VERSION_NBR_MASK (0xFFFFFFFF << MDMA_VERSION_NBR_SHIFT) /* NBR */

/******** Bit definition for MDMA_CFG register  ********/
#define MDMA_CFG_GLBINTEN (1 << 1) /* GLBINTEN */
#define MDMA_CFG_EN (1 << 0) /* EN */

